import { useEffect, useState, ChangeEvent } from 'react';

export type CheckState = 'idle' | 'checking' | 'available' | 'taken';

export function UsernameCheck({
  check,
}: {
  check: (name: string, signal: AbortSignal) => Promise<boolean>;
}) {
  const [name, setName] = useState<string>('');
  const [state, setState] = useState<CheckState>('idle');

  useEffect(() => {
    if (name.length < 3) {
      setState('idle');
      return;
    }

    const controller = new AbortController();
    const timer = setTimeout(async () => {
      setState('checking');
      try {
        const ok = await check(name, controller.signal);
        if (!controller.signal.aborted) setState(ok ? 'available' : 'taken');
      } catch (err) {
        if (err instanceof Error && err.name === 'AbortError') return;
      }
    }, 300);

    return () => {
      clearTimeout(timer);
      controller.abort();
    };
  }, [name, check]);

  return (
    <div>
      <input
        value={name}
        onChange={(e: ChangeEvent<HTMLInputElement>) => setName(e.target.value)}
      />
      <p>{state}</p>
    </div>
  );
}
